import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.*;
import java.util.logging.*;
import org.json.*;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger("AssetInventory");
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String action = req.getParameter("action");
        if ("search".equals(action)) {
            handleSearch(req, resp);
        } else if ("export".equals(action)) {
            handleExport(req, resp);
        } else {
            resp.sendError(400, "Unknown action");
        }
    }

    private void handleSearch(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String category = req.getParameter("category");
        String owner = req.getParameter("owner");
        String sortCol = req.getParameter("sort");

        // Validate sort column against allowlist
        if (sortCol != null && !sortCol.matches("^(name|created_at|value|location)$")) {
            sortCol = "name";
        }

        StringBuilder query = new StringBuilder(
            "SELECT id, name, category, owner, value, location FROM assets WHERE 1=1");

        if (category != null && !category.isEmpty()) {
            query.append(" AND category = '" + category + "'");
        }
        if (owner != null && !owner.isEmpty()) {
            query.append(" AND owner = '" + owner + "'");
        }
        if (sortCol != null) {
            query.append(" ORDER BY " + sortCol);
        }

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            JSONArray results = new JSONArray();
            while (rs.next()) {
                JSONObject row = new JSONObject();
                row.put("id", rs.getInt("id"));
                row.put("name", rs.getString("name"));
                row.put("category", rs.getString("category"));
                row.put("owner", rs.getString("owner"));
                row.put("value", rs.getDouble("value"));
                row.put("location", rs.getString("location"));
                results.put(row);
            }
            resp.setContentType("application/json");
            resp.getWriter().write(results.toString());
        } catch (SQLException e) {
            log.warning("Query failed: " + e.getMessage());
            resp.sendError(500, "Database error");
        }
    }

    private void handleExport(HttpServletRequest req, HttpServletResponse resp)
            throws IOException {
        String format = req.getParameter("format");
        String ids = req.getParameter("ids");

        if (ids == null || !ids.matches("^[0-9,]+$")) {
            resp.sendError(400, "Invalid IDs");
            return;
        }

        String query = "SELECT * FROM assets WHERE id IN (" + ids + ")";

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("text/csv");
            PrintWriter out = resp.getWriter();
            out.println("id,name,category,owner,value,location");
            while (rs.next()) {
                out.printf("%d,%s,%s,%s,%.2f,%s%n",
                    rs.getInt("id"), rs.getString("name"),
                    rs.getString("category"), rs.getString("owner"),
                    rs.getDouble("value"), rs.getString("location"));
            }
        } catch (SQLException e) {
            log.warning("Export failed: " + e.getMessage());
            resp.sendError(500, "Export error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Bulk update endpoint
        BufferedReader reader = req.getReader();
        StringBuilder body = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) body.append(line);

        JSONObject payload = new JSONObject(body.toString());
        String table = payload.optString("table", "assets");
        String field = payload.getString("field");
        String value = payload.getString("value");
        String condition = payload.getString("where");

        // Only allow updates to assets table
        if (!"assets".equals(table)) {
            resp.sendError(403, "Forbidden");
            return;
        }

        String update = String.format("UPDATE %s SET %s = '%s' WHERE %s",
            table, field, value, condition);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement()) {
            int rows = stmt.executeUpdate(update);
            resp.getWriter().write("{\"updated\": " + rows + "}");
        } catch (SQLException e) {
            log.warning("Update failed: " + e.getMessage());
            resp.sendError(500, "Update error");
        }
    }
}
